199	export function MeterBar({
200	  value,
201	  max,
202	  color = "#6f47f5",
203	  className = "",
204	}: {
205	  value: number;
206	  max: number;
207	  color?: string;
208	  className?: string;
209	}) {
210	  const pct = Math.min(100, (value / (max || 1)) * 100);
211	  return (
212	    <div className={`h-2 w-full rounded-full bg-white/[0.06] ${className}`}>
