49	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
50	  const user = await realUser();
51	  if (!user) redirect("/login");
52	  if (user.role !== "ADMIN") redirect("/dashboard");
53	  const imp = await impersonating();
54	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
55	
56	  const notifications = await db.notification.findMany({
57	    where: { userId: user.id },
58	    orderBy: { createdAt: "desc" },
59	    take: 15,
60	  });
61	
62	  return (
63	    <Shell
64	      nav={nav}
65	      tag="ops"
66	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
67	      notifications={notifications.map((n) => ({
68	        id: n.id,
69	        title: n.title,
70	        body: n.body,
71	        href: n.href,
72	        readAt: n.readAt ? n.readAt.toISOString() : null,
73	        createdAt: n.createdAt.toISOString(),
74	      }))}
75	    >
76	      {children}
77	    </Shell>
78	  );
79	}
