132	async function ownedServer(serverId: string) {
133	  const user = await requireUser();
134	  const server = await db.server.findUnique({ where: { id: serverId } });
135	  if (!server) throw new Error("Not found");
136	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
137	  return { user, server };
138	}
