1	import { Agent, fetch as undiciFetch } from "undici";
2	
3	const insecureAgent = new Agent({ connect: { rejectUnauthorized: false } });
4	
5	const BASE = process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
6	const NODE = process.env.PROXMOX_NODE ?? "";
7	const TOKEN = `PVEAPIToken=${process.env.PROXMOX_TOKEN_ID}=${process.env.PROXMOX_TOKEN_SECRET}`;
8	
9	export class ProxmoxError extends Error {
10	  constructor(message: string, public status: number, public body?: string) {
11	    super(message);
12	  }
13	}
14	
15	async function pveRequest(
16	  method: "GET" | "POST" | "PUT" | "DELETE",
17	  path: string,
18	  params?: Record<string, string | number | undefined>
19	): Promise<any> {
20	  const url = new URL(`${BASE}/api2/json${path}`);
21	  let body: string | undefined;
22	  const headers: Record<string, string> = { Authorization: TOKEN };
23	
24	  const clean = Object.fromEntries(
25	    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
26	  ) as Record<string, string>;
27	
28	  if (method === "GET" || method === "DELETE") {
29	    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
30	  } else {
31	    body = new URLSearchParams(clean as Record<string, string>).toString();
32	    headers["Content-Type"] = "application/x-www-form-urlencoded";
33	  }
34	
35	  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
36	  const text = await res.text();
37	  if (!res.ok) {
38	    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
39	  }
40	  try {
41	    return JSON.parse(text).data;
42	  } catch {
43	    return text;
44	  }
45	}
46	
47	export const pve = {
48	  get: (path: string, params?: Record<string, any>) => pveRequest("GET", path, params),
49	  post: (path: string, params?: Record<string, any>) => pveRequest("POST", path, params),
50	  put: (path: string, params?: Record<string, any>) => pveRequest("PUT", path, params),
51	  del: (path: string, params?: Record<string, any>) => pveRequest("DELETE", path, params),
52	};
