"use client";

import { useCallback, useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";

type Row = {
  time: number;
  cpu?: number | null;
  maxcpu?: number | null;
  memused?: number | null;
  memtotal?: number | null;
  netin?: number | null;
  netout?: number | null;
};

const TIMEFRAMES = [
  { tf: "hour", label: "1h" },
  { tf: "day", label: "24h" },
  { tf: "week", label: "7d" },
  { tf: "month", label: "30d" },
] as const;

function fmtTime(unixSec: number, tf: string): string {
  const d = new Date(unixSec * 1000);
  if (tf === "hour" || tf === "day") {
    return `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
  }
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

function pickLabels(rows: Row[], tf: string, count = 6): string[] {
  if (rows.length === 0) return [];
  const labels: string[] = [];
  for (let i = 0; i < count; i++) {
    const idx = Math.round((i / (count - 1)) * (rows.length - 1));
    labels.push(fmtTime(rows[idx].time, tf));
  }
  return labels;
}

export function NodeMetrics() {
  const [tf, setTf] = useState<string>("hour");
  const [rows, setRows] = useState<Row[] | null>(null);
  const [error, setError] = useState(false);

  const load = useCallback(async (timeframe: string) => {
    try {
      const res = await fetch(`/api/metrics?tf=${timeframe}`, { cache: "no-store" });
      if (!res.ok) throw new Error("bad status");
      const json = await res.json();
      const data: Row[] = (json.data ?? []).filter(
        (r: Row) => r && typeof r.time === "number" && r.cpu != null && r.memused != null
      );
      setRows(data);
      setError(false);
    } catch {
      setError(true);
      setRows([]);
    }
  }, []);

  useEffect(() => {
    setRows(null);
    load(tf);
    const t = setInterval(() => load(tf), 30_000);
    return () => clearInterval(t);
  }, [tf, load]);

  const memTotalGB = rows?.length ? (rows[rows.length - 1].memtotal ?? 0) / 1e9 : 0;
  const xLabels = rows ? pickLabels(rows, tf) : [];

  return (
    <div className="card">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="font-semibold">Node metrics</h2>
          <p className="text-xs text-slate-500">Hypervisor time series from Proxmox RRD · refreshes every 30s</p>
        </div>
        <div className="flex items-center gap-1 rounded-xl border border-white/[0.08] bg-white/[0.03] p-1">
          {TIMEFRAMES.map((t) => (
            <button
              key={t.tf}
              onClick={() => setTf(t.tf)}
              className={`rounded-lg px-3 py-1 text-xs font-medium transition-colors ${
                tf === t.tf ? "bg-brand-500/20 text-brand-300" : "text-slate-400 hover:text-slate-200"
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      {rows === null ? (
        <div className="space-y-4">
          <div className="skeleton h-40 w-full" />
          <div className="skeleton h-40 w-full" />
        </div>
      ) : error || rows.length === 0 ? (
        <p className="py-10 text-center text-sm text-slate-500">
          No metrics available — the Proxmox API did not return data for this window.
        </p>
      ) : (
        <div className="space-y-6">
          <div>
            <p className="section-label mb-2">CPU usage</p>
            <AreaChart
              id="node-cpu"
              series={[{ name: "CPU %", data: rows.map((r) => (r.cpu ?? 0) * 100), color: "#8a70fb" }]}
              maxY={100}
              height={170}
              yLabel={(v) => `${v.toFixed(0)}%`}
              xLabels={xLabels}
            />
          </div>
          <div>
            <p className="section-label mb-2">Memory used</p>
            <AreaChart
              id="node-mem"
              series={[{ name: "Mem GB", data: rows.map((r) => (r.memused ?? 0) / 1e9), color: "#3b82f6" }]}
              maxY={memTotalGB > 0 ? memTotalGB : undefined}
              height={170}
              yLabel={(v) => `${v.toFixed(1)}G`}
              xLabels={xLabels}
            />
          </div>
          <div>
            <p className="section-label mb-2">Network throughput</p>
            <AreaChart
              id="node-net"
              series={[
                { name: "In KB/s", data: rows.map((r) => (r.netin ?? 0) / 1024, ), color: "#34d399" },
                { name: "Out KB/s", data: rows.map((r) => (r.netout ?? 0) / 1024), color: "#fbbf24" },
              ]}
              height={170}
              yLabel={(v) => `${v.toFixed(0)}K`}
              xLabels={xLabels}
            />
            <div className="mt-2 flex gap-4 text-xs text-slate-400">
              <span className="inline-flex items-center gap-1.5">
                <span className="h-2 w-2 rounded-full bg-emerald-400" /> inbound KB/s
              </span>
              <span className="inline-flex items-center gap-1.5">
                <span className="h-2 w-2 rounded-full bg-amber-400" /> outbound KB/s
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useTransition } from "react";
import { impersonateUser } from "@/lib/actions-account";

export function ImpersonateButton({ userId, email, small }: { userId: string; email: string; small?: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={small ? "btn-ghost py-1 text-xs" : "btn-secondary"}
      disabled={pending}
      onClick={() => {
        if (window.confirm(`Impersonate ${email}? You will see their customer portal until you exit.`)) {
          start(() => impersonateUser(userId));
        }
      }}
    >
      {pending ? "Switching…" : "Impersonate"}
    </button>
  );
