"use client";

import { useState, useTransition } from "react";
import { serverAction } from "@/lib/actions";

export function PowerActions({ serverId, status }: { serverId: string; status: string }) {
  const [pending, start] = useTransition();
  const run = (action: "start" | "stop" | "reboot") => {
    if (window.confirm(`Send ${action.toUpperCase()} to this server?`)) {
      start(() => serverAction(serverId, action));
    }
  };
  const busy = pending || ["PROVISIONING", "REINSTALLING", "DELETING", "PENDING"].includes(status);
  return (
    <div className="flex items-center gap-2">
      <button className="btn-secondary py-1.5" disabled={busy || status === "RUNNING"} onClick={() => run("start")}>
        Start
      </button>
      <button className="btn-secondary py-1.5" disabled={busy || status === "STOPPED"} onClick={() => run("stop")}>
        Stop
      </button>
      <button className="btn-secondary py-1.5" disabled={busy || status !== "RUNNING"} onClick={() => run("reboot")}>
        Reboot
      </button>
    </div>
  );
}

export function DangerDelete({ serverId, hostname }: { serverId: string; hostname: string }) {
  const [pending, start] = useTransition();
  const [confirmText, setConfirmText] = useState("");
  const [armed, setArmed] = useState(false);

  if (!armed) {
    return (
      <button className="btn-danger" onClick={() => setArmed(true)}>
        Delete server…
      </button>
    );
  }
  return (
    <div className="flex flex-wrap items-center gap-2">
      <input
        className="input w-56 py-1.5 font-mono text-xs"
        placeholder={`type "${hostname}" to confirm`}
        value={confirmText}
        onChange={(e) => setConfirmText(e.target.value)}
        autoFocus
      />
      <button
        className="btn-danger py-1.5"
        disabled={pending || confirmText !== hostname}
        onClick={() => {
          if (
            window.confirm(
              `Really destroy ${hostname}? The VM, its disk, IP and port forwards are removed permanently.`
            )
          ) {
            start(() => serverAction(serverId, "delete"));
          }
        }}
      >
        {pending ? "Deleting…" : "Destroy permanently"}
      </button>
      <button
        className="btn-ghost py-1.5"
        onClick={() => {
          setArmed(false);
          setConfirmText("");
        }}
      >
        Cancel
      </button>
    </div>
  );
}

