      <div className="flex items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "Sending…" : "Send staff reply"}
        </button>
        {state?.error && <span className="text-xs text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

export function PrioritySelect({ ticketId, priority }: { ticketId: string; priority: string }) {
  const [pending, start] = useTransition();
  return (
    <select
      className="input w-auto py-1.5 text-xs"
      defaultValue={priority}
      disabled={pending}
      onChange={(e) =>
        start(() => setTicketPriority(ticketId, e.target.value as "LOW" | "NORMAL" | "HIGH" | "URGENT"))
      }
    >
      <option value="LOW">Low</option>
      <option value="NORMAL">Normal</option>
      <option value="HIGH">High</option>
      <option value="URGENT">Urgent</option>
    </select>
  );
}

export function TicketStatusButton({ ticketId, closed }: { ticketId: string; closed: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={closed ? "btn-secondary py-1.5" : "btn-danger py-1.5"}
      disabled={pending}
      onClick={() => start(() => setTicketStatus(ticketId, closed ? "OPEN" : "CLOSED"))}
    >
      {closed ? "Reopen ticket" : "Close ticket"}
    </button>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { nodeStatus, storageStatus } from "@/lib/proxmox";
import { PageHeader, StatCard, StatusDot, Badge, fmtBytes, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { AreaChart, MeterBar } from "@/components/ui/charts";
import { AutoRefresh } from "@/components/AutoRefresh";

export const dynamic = "force-dynamic";

function dayKey(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export default async function AdminOverview() {
  await requireAdmin();

  const since24h = new Date(Date.now() - 24 * 3600_000);
  const since14d = new Date(Date.now() - 14 * 86400_000);

  const [
    activeServers,
    serverOwners,
    runningCount,
    totalServers,
    openTickets,
    failedJobs24h,
    liabilities,
    revenueTx,
    activeJobs,
    recentAudit,
  ] = await Promise.all([
    db.server.findMany({
      where: { isFree: false, status: { notIn: ["DELETING"] } },
      include: { plan: { select: { priceCents: true } } },
    }),
    db.server.groupBy({ by: ["userId"] }),
    db.server.count({ where: { status: "RUNNING" } }),
    db.server.count({ where: { status: { notIn: ["DELETING"] } } }),
    db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } }),
    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since24h } } }),
    db.user.aggregate({ _sum: { balanceCents: true } }),
    db.walletTransaction.findMany({
      where: { amountCents: { lt: 0 }, createdAt: { gte: since14d } },
      select: { amountCents: true, createdAt: true },
    }),
    db.job.findMany({
      where: { status: { in: ["QUEUED", "RUNNING"] } },
      include: { server: { select: { hostname: true, id: true } } },
      orderBy: { createdAt: "asc" },
      take: 8,
    }),
    db.auditLog.findMany({
      include: { user: { select: { email: true } } },
      orderBy: { createdAt: "desc" },
      take: 10,
    }),
  ]);

  const mrrCents = activeServers.reduce((n, s) => n + s.plan.priceCents, 0);

  // Revenue last 14 days, grouped by day
  const days: string[] = [];
  const revByDay = new Map<string, number>();
  for (let i = 13; i >= 0; i--) {
    const k = dayKey(new Date(Date.now() - i * 86400_000));
    days.push(k);
    revByDay.set(k, 0);
  }
  for (const tx of revenueTx) {
    const k = dayKey(tx.createdAt);
    if (revByDay.has(k)) revByDay.set(k, (revByDay.get(k) ?? 0) + Math.abs(tx.amountCents));
  }
  const revSeries = days.map((k) => (revByDay.get(k) ?? 0) / 100);
  const revTotal14d = revSeries.reduce((a, b) => a + b, 0);

  // Live hypervisor + storage (graceful fallback)
  let node: any = null;
  let vmdata: any = null;
  let backup: any = null;
  try {
    [node, vmdata, backup] = await Promise.all([
      nodeStatus(),
      storageStatus("vmdata"),
      storageStatus("backup"),
    ]);
  } catch {
    // Proxmox unreachable — cards render a fallback below
  }

  const uptimeDays = node ? Math.floor(node.uptime / 86400) : 0;
  const uptimeHours = node ? Math.floor((node.uptime % 86400) / 3600) : 0;

  return (
    <div className="space-y-6">
      {activeJobs.length > 0 && <AutoRefresh />}
      <PageHeader title="Operations overview" sub="Live command center for the Nxeon platform.">
        <Link href="/admin/monitoring" className="btn-secondary">
          Monitoring
        </Link>
        <Link href="/admin/grant" className="btn-primary">
          Grant VPS
        </Link>
      </PageHeader>

      {/* KPI row */}
      <div className="grid grid-cols-2 gap-4 lg:grid-cols-3 xl:grid-cols-6">
        <StatCard label="MRR" value={fmtMoney(mrrCents)} delta={`${activeServers.length} paid servers`} href="/admin/subscriptions" />
        <StatCard label="Active customers" value={String(serverOwners.length)} delta="with ≥1 server" href="/admin/users" />
        <StatCard
          label="Servers"
          value={String(totalServers)}
          delta={`${runningCount} running`}
          deltaGood={runningCount > 0}
          href="/admin/servers"
        />
        <StatCard
          label="Open tickets"
          value={String(openTickets)}
          delta={openTickets > 0 ? "awaiting staff" : "queue clear"}
          deltaGood={openTickets === 0}
          href="/admin/support"
        />
        <StatCard
          label="Failed jobs (24h)"
          value={String(failedJobs24h)}
          delta={failedJobs24h > 0 ? "needs attention" : "all healthy"}
          deltaGood={failedJobs24h === 0}
          href="/admin/provisioning"
        />
        <StatCard
          label="Wallet liabilities"
          value={fmtMoney(liabilities._sum.balanceCents ?? 0)}
          delta="customer balances"
          href="/admin/billing"
        />
      </div>

      {/* Health + revenue row */}
      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-semibold">Hypervisor health</h2>
            {node ? <StatusDot status="online" label="online" /> : <StatusDot status="ERROR" label="unreachable" />}
          </div>
          {node ? (
            <div className="space-y-4 text-sm">
              <div>
                <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                  <span>CPU</span>
                  <span>{(node.cpu * 100).toFixed(1)}% of {node.cpuinfo?.cpus ?? "?"} threads</span>
                </div>
                <MeterBar value={node.cpu * 100} max={100} color="#8a70fb" />
              </div>
              <div>
                <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                  <span>Memory</span>
                  <span>
                    {fmtBytes(node.memory?.used ?? 0)} / {fmtBytes(node.memory?.total ?? 0)}
                  </span>
                </div>
                <MeterBar value={node.memory?.used ?? 0} max={node.memory?.total ?? 1} color="#3b82f6" />
              </div>
              <dl className="grid grid-cols-2 gap-x-4 gap-y-2 pt-1 text-xs">
                <div className="flex justify-between">
                  <dt className="text-slate-500">Uptime</dt>
                  <dd>{uptimeDays}d {uptimeHours}h</dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-slate-500">Load</dt>
                  <dd className="font-mono">{Array.isArray(node.loadavg) ? node.loadavg.join(" ") : "—"}</dd>
                </div>
                <div className="col-span-2 flex justify-between">
                  <dt className="text-slate-500">Kernel</dt>
                  <dd className="truncate pl-3 text-right">{node.kversion?.split(" ").slice(0, 2).join(" ") ?? "—"}</dd>
                </div>
              </dl>
            </div>
          ) : (
            <p className="py-6 text-sm text-slate-500">
              Could not reach the Proxmox API. Node stats will reappear once the hypervisor responds.
            </p>
          )}
        </div>

        <div className="card">
          <h2 className="mb-4 font-semibold">Storage pools</h2>
          {vmdata || backup ? (
            <div className="space-y-5 text-sm">
              {vmdata && (
                <div>
                  <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                    <span>vmdata · NVMe (VM disks)</span>
                    <span>
                      {fmtBytes(vmdata.used)} / {fmtBytes(vmdata.total)}
                    </span>
                  </div>
                  <MeterBar
                    value={vmdata.used}
                    max={vmdata.total}
                    color={vmdata.used / vmdata.total > 0.8 ? "#f59e0b" : "#8a70fb"}
                  />
                </div>
              )}
              {backup && (
                <div>
                  <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                    <span>backup · HDD (backups, snippets)</span>
                    <span>
                      {fmtBytes(backup.used)} / {fmtBytes(backup.total)}
                    </span>
                  </div>
                  <MeterBar
                    value={backup.used}
                    max={backup.total}
                    color={backup.used / backup.total > 0.8 ? "#f59e0b" : "#34d399"}
                  />
                </div>
              )}
              <p className="text-xs text-slate-500">
                Full pool detail on the{" "}
                <Link href="/admin/infrastructure" className="text-brand-300 hover:underline">
                  infrastructure page
                </Link>
                .
              </p>
            </div>
          ) : (
            <p className="py-6 text-sm text-slate-500">Storage stats unavailable — Proxmox API unreachable.</p>
          )}
        </div>

        <div className="card">
          <div className="mb-2 flex items-center justify-between">
            <h2 className="font-semibold">Revenue · last 14 days</h2>
            <span className="text-sm font-semibold text-emerald-400">${revTotal14d.toFixed(2)}</span>
          </div>
          <AreaChart
            id="rev14"
            series={[{ name: "Revenue $", data: revSeries, color: "#34d399" }]}
            height={180}
            yLabel={(v) => `$${v.toFixed(0)}`}
            xLabels={[days[0].slice(5), days[6].slice(5), days[13].slice(5)]}
          />
        </div>
      </div>

      {/* Queue + activity + quick actions */}
      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <h2 className="font-semibold">Provisioning queue</h2>
            <Link href="/admin/provisioning" className="text-xs text-brand-300 hover:underline">
              View all →
            </Link>
          </div>
          {activeJobs.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">Queue is empty — no jobs in flight.</p>
          ) : (
            <div className="overflow-x-auto p-2 pt-3">
              <table className="table-shell">
                <tbody>
                  {activeJobs.map((j) => (
                    <tr key={j.id}>
                      <td>
                        {j.server ? (
                          <Link href={`/admin/servers/${j.server.id}`} className="font-medium hover:text-brand-300">
                            {j.server.hostname}
                          </Link>
                        ) : (
                          <span className="text-slate-500">—</span>
                        )}
                      </td>
                      <td className="text-xs text-slate-400">{j.type.toLowerCase().replace(/_/g, " ")}</td>
                      <td className="text-right">
                        <StatusDot status={j.status} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <h2 className="font-semibold">Live activity</h2>
            <Link href="/admin/audit" className="text-xs text-brand-300 hover:underline">
              Audit log →
            </Link>
          </div>
          <ul className="divide-y divide-white/[0.05] px-5 py-2">
            {recentAudit.length === 0 && <li className="py-6 text-sm text-slate-500">No activity yet.</li>}
            {recentAudit.map((a) => (
              <li key={a.id} className="flex items-baseline justify-between gap-3 py-2.5 text-sm">
                <div className="min-w-0">
                  <span className="font-medium">{a.action}</span>
                  <span className="ml-2 truncate text-xs text-slate-500">{a.user?.email ?? "system"}</span>
                </div>
                <span className="shrink-0 text-xs text-slate-500">{timeAgo(a.createdAt)}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="card">
          <h2 className="mb-4 font-semibold">Quick actions</h2>
          <div className="grid grid-cols-2 gap-3">
            <Link href="/admin/grant" className="card card-hover p-4 text-sm">
              <p className="font-medium">Grant VPS</p>
              <p className="mt-1 text-xs text-slate-500">Deploy a free server for a client</p>
            </Link>
            <Link href="/admin/users" className="card card-hover p-4 text-sm">
              <p className="font-medium">Add client credit</p>
              <p className="mt-1 text-xs text-slate-500">Top up a wallet from the roster</p>
            </Link>
            <div className="card p-4 text-sm opacity-50">
              <div className="flex items-center gap-2">
                <p className="font-medium">New announcement</p>
                <Badge tone="amber">soon</Badge>
              </div>
              <p className="mt-1 text-xs text-slate-500">Broadcasts ship with email support</p>
            </div>
            <Link href="/admin/monitoring" className="card card-hover p-4 text-sm">
              <p className="font-medium">Open monitoring</p>
              <p className="mt-1 text-xs text-slate-500">Node + per-VM live metrics</p>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

