            series={[{ name: "Revenue $", data: revSeries, color: "#34d399" }]}
            height={180}
            yLabel={(v) => `$${v.toFixed(0)}`}
            xLabels={[days[0].slice(5), days[6].slice(5), days[13].slice(5)]}
          />
        </div>
      </div>

      {/* Queue + activity + quick actions */}
      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <h2 className="font-semibold">Provisioning queue</h2>
            <Link href="/admin/provisioning" className="text-xs text-brand-300 hover:underline">
              View all →
            </Link>
          </div>
          {activeJobs.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">Queue is empty — no jobs in flight.</p>
          ) : (
            <div className="overflow-x-auto p-2 pt-3">
              <table className="table-shell">
                <tbody>
                  {activeJobs.map((j) => (
                    <tr key={j.id}>
                      <td>
                        {j.server ? (
                          <Link href={`/admin/servers/${j.server.id}`} className="font-medium hover:text-brand-300">
                            {j.server.hostname}
                          </Link>
                        ) : (
                          <span className="text-slate-500">—</span>
                        )}
                      </td>
                      <td className="text-xs text-slate-400">{j.type.toLowerCase().replace(/_/g, " ")}</td>
                      <td className="text-right">
                        <StatusDot status={j.status} />
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <h2 className="font-semibold">Live activity</h2>
            <Link href="/admin/audit" className="text-xs text-brand-300 hover:underline">
              Audit log →
            </Link>
          </div>
          <ul className="divide-y divide-white/[0.05] px-5 py-2">
            {recentAudit.length === 0 && <li className="py-6 text-sm text-slate-500">No activity yet.</li>}
            {recentAudit.map((a) => (
              <li key={a.id} className="flex items-baseline justify-between gap-3 py-2.5 text-sm">
                <div className="min-w-0">
                  <span className="font-medium">{a.action}</span>
                  <span className="ml-2 truncate text-xs text-slate-500">{a.user?.email ?? "system"}</span>
                </div>
                <span className="shrink-0 text-xs text-slate-500">{timeAgo(a.createdAt)}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="card">
          <h2 className="mb-4 font-semibold">Quick actions</h2>
          <div className="grid grid-cols-2 gap-3">
            <Link href="/admin/grant" className="card card-hover p-4 text-sm">
              <p className="font-medium">Grant VPS</p>
              <p className="mt-1 text-xs text-slate-500">Deploy a free server for a client</p>
            </Link>
            <Link href="/admin/users" className="card card-hover p-4 text-sm">
              <p className="font-medium">Add client credit</p>
              <p className="mt-1 text-xs text-slate-500">Top up a wallet from a client profile</p>
            </Link>
            <div className="card p-4 text-sm opacity-50">
              <div className="flex items-center gap-2">
                <p className="font-medium">New announcement</p>
                <Badge tone="amber">soon</Badge>
              </div>
              <p className="mt-1 text-xs text-slate-500">Broadcasts ship with email support</p>
            </div>
            <Link href="/admin/monitoring" className="card card-hover p-4 text-sm">
              <p className="font-medium">Open monitoring</p>
              <p className="mt-1 text-xs text-slate-500">Node + per-VM live metrics</p>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, fmtMoney } from "@/components/ui/primitives";
import { AreaChart, Donut } from "@/components/ui/charts";

export const dynamic = "force-dynamic";

const PLAN_COLORS = ["#8a70fb", "#3b82f6", "#34d399", "#fbbf24", "#f472b6", "#22d3ee", "#a3e635", "#fb7185"];

function monthKey(d: Date): string {
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}`;
}

export default async function AdminAnalytics() {
  await requireAdmin();

  const now = new Date();
  const since30d = new Date(Date.now() - 30 * 86400_000);
  const sixMonthsAgo = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 5, 1));
  const twelveWeeksAgo = new Date(Date.now() - 12 * 7 * 86400_000);

  const [charges6mo, signups, activeServers, deletions30d, spend30d, firstUser] = await Promise.all([
    db.walletTransaction.findMany({
      where: { amountCents: { lt: 0 }, createdAt: { gte: sixMonthsAgo } },
      select: { amountCents: true, createdAt: true },
    }),
    db.user.findMany({
      where: { createdAt: { gte: twelveWeeksAgo } },
      select: { createdAt: true },
    }),
    db.server.findMany({
      where: { status: { notIn: ["DELETING"] } },
      include: { plan: { select: { id: true, name: true, priceCents: true } }, user: { select: { id: true, email: true, name: true } } },
    }),
    db.auditLog.count({ where: { action: "server.delete", createdAt: { gte: since30d } } }),
    db.walletTransaction.aggregate({
      where: { amountCents: { lt: 0 }, createdAt: { gte: since30d } },
      _sum: { amountCents: true },
    }),
    db.user.findFirst({ orderBy: { createdAt: "asc" }, select: { createdAt: true } }),
  ]);

  // Revenue by month (last 6 calendar months)
  const monthKeys: string[] = [];
  const revByMonth = new Map<string, number>();
  for (let i = 5; i >= 0; i--) {
    const k = monthKey(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - i, 1)));
    monthKeys.push(k);
    revByMonth.set(k, 0);
  }
  for (const tx of charges6mo) {
    const k = monthKey(tx.createdAt);
    if (revByMonth.has(k)) revByMonth.set(k, (revByMonth.get(k) ?? 0) + Math.abs(tx.amountCents));
  }
  const revSeries = monthKeys.map((k) => (revByMonth.get(k) ?? 0) / 100);

  // Signups by week (last 12 weeks)
  const weekBuckets = Array.from({ length: 12 }, () => 0);
  for (const u of signups) {
    const weeksAgo = Math.floor((Date.now() - u.createdAt.getTime()) / (7 * 86400_000));
    if (weeksAgo >= 0 && weeksAgo < 12) weekBuckets[11 - weeksAgo]++;
  }

  // Plan distribution
  const byPlan = new Map<string, { name: string; count: number }>();
  for (const s of activeServers) {
    const cur = byPlan.get(s.plan.id) ?? { name: s.plan.name, count: 0 };
    cur.count++;
    byPlan.set(s.plan.id, cur);
  }
  const planEntries = [...byPlan.values()].sort((a, b) => b.count - a.count);

  // ARPU
  const revenue30dCents = -(spend30d._sum.amountCents ?? 0);
  const activeCustomers = new Set(activeServers.map((s) => s.user.id)).size;
  const arpuCents = activeCustomers > 0 ? Math.round(revenue30dCents / activeCustomers) : 0;

  // Top customers by committed monthly spend (active paid servers)
  const byCustomer = new Map<string, { email: string; name: string; mrrCents: number; servers: number }>();
  for (const s of activeServers) {
    const cur = byCustomer.get(s.user.id) ?? { email: s.user.email, name: s.user.name, mrrCents: 0, servers: 0 };
    cur.servers++;
    if (!s.isFree) cur.mrrCents += s.plan.priceCents;
    byCustomer.set(s.user.id, cur);
  }
  const topCustomers = [...byCustomer.entries()]
    .sort((a, b) => b[1].mrrCents - a[1].mrrCents)
    .slice(0, 8);

  const platformAgeDays = firstUser ? Math.floor((Date.now() - firstUser.createdAt.getTime()) / 86400_000) : 0;
  const shortHistory = platformAgeDays < 30;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Business analytics"
        sub={
          shortHistory
            ? `All figures since launch (${platformAgeDays}d of history) — trends firm up as data accrues.`
            : "Revenue, growth and customer metrics from live platform data."
        }
      />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Revenue · last 30d" value={fmtMoney(revenue30dCents)} delta={shortHistory ? "since launch" : "trailing 30 days"} />
        <StatCard
          label="ARPU · 30d"
          value={fmtMoney(arpuCents)}
          delta={`across ${activeCustomers} active customer${activeCustomers === 1 ? "" : "s"}`}
        />
        <StatCard
          label="Servers deleted · 30d"
          value={String(deletions30d)}
          delta={deletions30d === 0 ? "no churn signal" : "churn proxy (delete actions)"}
          deltaGood={deletions30d === 0}
        />
        <StatCard label="New signups · 12w" value={String(signups.length)} spark={weekBuckets} sparkColor="#3b82f6" />
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <div className="card">
          <h2 className="mb-1 font-semibold">Revenue by month</h2>
          <p className="mb-3 text-xs text-slate-500">
            Wallet charges (orders + renewals), grouped by calendar month{shortHistory ? " — history starts at launch" : ""}.
          </p>
          <AreaChart
            id="rev-month"
            series={[{ name: "Revenue $", data: revSeries, color: "#34d399" }]}
            height={200}
            yLabel={(v) => `$${v.toFixed(0)}`}
            xLabels={monthKeys.map((k) => k.slice(5))}
          />
        </div>

        <div className="card">
          <h2 className="mb-1 font-semibold">Customer signups by week</h2>
          <p className="mb-3 text-xs text-slate-500">New accounts registered per week, last 12 weeks.</p>
          <AreaChart
            id="signups-week"
            series={[{ name: "Signups", data: weekBuckets, color: "#3b82f6" }]}
            height={200}
            yLabel={(v) => v.toFixed(0)}
            xLabels={["-12w", "-9w", "-6w", "-3w", "now"]}
          />
        </div>
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <div className="card">
          <h2 className="mb-1 font-semibold">Plan distribution</h2>
          <p className="mb-4 text-xs text-slate-500">Active servers per plan (free and paid).</p>
          {planEntries.length === 0 ? (
            <p className="py-8 text-center text-sm text-slate-500">No active servers yet.</p>
          ) : (
            <div className="flex items-center gap-6">
              <Donut
                segments={planEntries.map((p, i) => ({ value: p.count, color: PLAN_COLORS[i % PLAN_COLORS.length] }))}
                centerLabel={String(activeServers.length)}
                centerSub="servers"
              />
              <ul className="space-y-2 text-sm">
                {planEntries.map((p, i) => (
                  <li key={p.name} className="flex items-center gap-2">
                    <span
                      className="h-2.5 w-2.5 rounded-full"
                      style={{ background: PLAN_COLORS[i % PLAN_COLORS.length] }}
                    />
                    <span>{p.name}</span>
                    <span className="text-xs text-slate-500">×{p.count}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>

        <div className="card p-0 xl:col-span-2">
          <div className="px-5 pt-5">
            <h2 className="font-semibold">Top customers by monthly spend</h2>
            <p className="mt-1 text-xs text-slate-500">
              Committed MRR from each customer&apos;s active paid servers (free servers excluded).
            </p>
          </div>
          {topCustomers.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No customers with servers yet.</p>
          ) : (
            <div className="overflow-x-auto pt-3">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Customer</th>
                    <th>Servers</th>
                    <th className="text-right">Monthly spend</th>
                  </tr>
                </thead>
                <tbody>
                  {topCustomers.map(([id, c]) => (
                    <tr key={id}>
                      <td>
                        <Link href={`/admin/users/${id}`} className="font-medium hover:text-brand-300">
                          {c.name}
                        </Link>
                        <span className="ml-2 text-xs text-slate-500">{c.email}</span>
                      </td>
                      <td>{c.servers}</td>
                      <td className="text-right font-medium">
                        {c.mrrCents > 0 ? `${fmtMoney(c.mrrCents)}/mo` : <span className="text-slate-500">free only</span>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

