import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { ServerStatus } from "@prisma/client";
import { PageHeader, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { SuspendServerButton } from "@/components/AdminControls";
import { AutoRefresh } from "@/components/AutoRefresh";

export const dynamic = "force-dynamic";

const STATUSES = Object.values(ServerStatus);
const TRANSITIONAL: ServerStatus[] = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];

export default async function AdminServers({
  searchParams,
}: {
  searchParams: Promise<{ status?: string }>;
}) {
  await requireAdmin();
  const { status } = await searchParams;
  const statusFilter = STATUSES.includes(status as ServerStatus) ? (status as ServerStatus) : undefined;

  const [servers, counts] = await Promise.all([
    db.server.findMany({
      where: statusFilter ? { status: statusFilter } : undefined,
      include: {
        user: { select: { id: true, email: true } },
        plan: { select: { name: true, priceCents: true } },
      },
      orderBy: { createdAt: "desc" },
    }),
    db.server.groupBy({ by: ["status"], _count: true }),
  ]);

  const countByStatus = new Map(counts.map((c) => [c.status, c._count]));
  const total = counts.reduce((n, c) => n + c._count, 0);
  const anyTransitional = servers.some((s) => TRANSITIONAL.includes(s.status));

  return (
    <div className="space-y-6">
      {anyTransitional && <AutoRefresh />}
      <PageHeader title="Server fleet" sub={`${total} server${total === 1 ? "" : "s"} across all clients.`} />

      {/* Status filter chips */}
      <div className="flex flex-wrap items-center gap-2">
        <Link
          href="/admin/servers"
          className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
            !statusFilter
              ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
              : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
          }`}
        >
          All · {total}
        </Link>
        {STATUSES.filter((s) => countByStatus.has(s)).map((s) => (
          <Link
            key={s}
            href={`/admin/servers?status=${s}`}
            className={`rounded-full border px-3 py-1 text-xs font-medium transition-colors ${
              statusFilter === s
                ? "border-brand-500/40 bg-brand-500/10 text-brand-300"
                : "border-white/10 bg-white/[0.04] text-slate-400 hover:text-slate-200"
            }`}
          >
            {s.toLowerCase().replace(/_/g, " ")} · {countByStatus.get(s)}
          </Link>
        ))}
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Hostname</th>
              <th>Owner</th>
              <th>Plan</th>
              <th>VMID</th>
              <th>SSH endpoint</th>
              <th>Status</th>
              <th>Expires</th>
              <th className="text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {servers.length === 0 && (
              <tr>
                <td colSpan={8} className="py-10 text-center text-slate-500">
                  No servers{statusFilter ? ` in status ${statusFilter.toLowerCase()}` : " yet"}.
                </td>
              </tr>
            )}
            {servers.map((s) => (
              <tr key={s.id}>
                <td>
                  <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
                    {s.hostname}
                  </Link>
                  {s.isFree && (
                    <span className="ml-2">
                      <Badge tone="green">free</Badge>
                    </span>
                  )}
                </td>
                <td>
                  <Link href={`/admin/users/${s.user.id}`} className="text-slate-300 hover:text-brand-300">
                    {s.user.email}
                  </Link>
                </td>
                <td>
                  {s.plan.name}
                  {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(s.plan.priceCents)}/mo</span>}
                </td>
                <td className="font-mono text-xs">{s.vmid ?? "—"}</td>
                <td className="font-mono text-xs">
                  {s.ipAddress ? `${s.ipAddress}${s.sshPort ? `:${s.sshPort}` : ""}` : "—"}
                </td>
                <td>
                  <StatusDot status={s.status} />
                </td>
                <td className="text-xs">
                  {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
                </td>
                <td className="text-right">
                  {s.status !== "DELETING" && (
                    <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { vmStatus } from "@/lib/proxmox";
import { PageHeader, StatusDot, Badge, fmtBytes, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { SuspendServerButton } from "@/components/AdminControls";
import { ExtendForm, FreeToggle } from "@/components/SubscriptionControls";
import { PowerActions, DangerDelete } from "@/components/admin/ServerAdminActions";
import { AutoRefresh } from "@/components/AutoRefresh";

export const dynamic = "force-dynamic";

const TRANSITIONAL = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"];

export default async function AdminServerDetail({ params }: { params: Promise<{ id: string }> }) {
  await requireAdmin();
  const { id } = await params;

  const server = await db.server.findUnique({
    where: { id },
    include: {
      user: { select: { id: true, email: true, name: true } },
      plan: true,
      osTemplate: true,
      portForwards: { orderBy: { publicPort: "asc" } },
      jobs: { orderBy: { createdAt: "desc" }, take: 25 },
    },
  });
  if (!server) notFound();

  const hasActiveJob = server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");

  // Live VM stats (read-only, graceful fallback)
  let live: any = null;
  if (server.vmid) {
    try {
      live = await vmStatus(server.vmid);
    } catch {
      live = null;
    }
  }

  const uptimeDays = live?.uptime ? Math.floor(live.uptime / 86400) : 0;
  const uptimeHours = live?.uptime ? Math.floor((live.uptime % 86400) / 3600) : 0;

  return (
    <div className="space-y-6">
      {(hasActiveJob || TRANSITIONAL.includes(server.status)) && <AutoRefresh />}
      <PageHeader title={server.hostname} sub={`Admin server detail · created ${server.createdAt.toISOString().slice(0, 10)}`}>
        <StatusDot status={server.status} />
        {server.isFree && <Badge tone="green">free</Badge>}
        <Link href={`/admin/users/${server.user.id}`} className="btn-secondary">
          Owner: {server.user.email}
        </Link>
      </PageHeader>

      {server.suspendedNote && (
        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          Suspension note: {server.suspendedNote}
        </div>
      )}

      <div className="grid gap-4 xl:grid-cols-3">
        {/* Configuration */}
        <div className="card xl:col-span-2">
          <h2 className="mb-4 font-semibold">Configuration</h2>
          <dl className="grid grid-cols-2 gap-x-6 gap-y-3 text-sm md:grid-cols-3">
            <div>
              <dt className="text-xs text-slate-500">Plan</dt>
              <dd className="mt-0.5 font-medium">
                {server.plan.name}
                {!server.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(server.plan.priceCents)}/mo</span>}
              </dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Resources</dt>
              <dd className="mt-0.5">
                {server.plan.cpuCores} vCPU · {(server.plan.ramMB / 1024).toFixed(1)} GB RAM · {server.plan.diskGB} GB
              </dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Operating system</dt>
              <dd className="mt-0.5">{server.osTemplate.name}</dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">VMID</dt>
              <dd className="mt-0.5 font-mono">{server.vmid ?? "—"}</dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Private IP</dt>
              <dd className="mt-0.5 font-mono">{server.ipAddress ?? "—"}</dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">SSH port (public)</dt>
              <dd className="mt-0.5 font-mono">{server.sshPort ?? "—"}</dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Auto-renew</dt>
              <dd className="mt-0.5">{server.isFree ? "n/a (free)" : server.autoRenew ? "on" : "off"}</dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Expires</dt>
              <dd className="mt-0.5">
                {server.isFree ? "never" : server.expiresAt ? server.expiresAt.toISOString().slice(0, 10) : "—"}
              </dd>
            </div>
            <div>
              <dt className="text-xs text-slate-500">Bandwidth</dt>
              <dd className="mt-0.5">{server.plan.bandwidthTB} TB/mo</dd>
            </div>
          </dl>

          <div className="divider" />
          <h3 className="mb-2 text-sm font-semibold">Port forwards</h3>
          {server.portForwards.length === 0 ? (
            <p className="text-sm text-slate-500">No port forwards configured.</p>
          ) : (
            <div className="overflow-x-auto">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Public port</th>
                    <th>Guest port</th>
                    <th>Protocol</th>
                  </tr>
                </thead>
                <tbody>
                  {server.portForwards.map((pf) => (
                    <tr key={pf.id}>
                      <td className="font-mono text-xs">{pf.publicPort}</td>
                      <td className="font-mono text-xs">{pf.guestPort}</td>
                      <td className="text-xs uppercase">{pf.protocol}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Live stats */}
        <div className="card">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-semibold">Live VM stats</h2>
            {live ? (
              <StatusDot status={live.status === "running" ? "online" : "STOPPED"} label={live.status} />
            ) : (
              <Badge tone="slate">unavailable</Badge>
            )}
          </div>
          {live ? (
            <div className="space-y-4 text-sm">
              <div>
                <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                  <span>CPU</span>
                  <span>{((live.cpu ?? 0) * 100).toFixed(1)}% of {live.cpus ?? server.plan.cpuCores} vCPU</span>
                </div>
                <MeterBar value={(live.cpu ?? 0) * 100} max={100} color="#8a70fb" />
              </div>
              <div>
                <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                  <span>Memory</span>
                  <span>
                    {fmtBytes(live.mem ?? 0)} / {fmtBytes(live.maxmem ?? 0)}
                  </span>
                </div>
                <MeterBar value={live.mem ?? 0} max={live.maxmem ?? 1} color="#3b82f6" />
              </div>
              <dl className="space-y-2 pt-1 text-xs">
                <div className="flex justify-between">
                  <dt className="text-slate-500">Uptime</dt>
                  <dd>{live.uptime ? `${uptimeDays}d ${uptimeHours}h` : "—"}</dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-slate-500">Net in / out</dt>
                  <dd className="font-mono">
                    {fmtBytes(live.netin ?? 0)} / {fmtBytes(live.netout ?? 0)}
                  </dd>
                </div>
                <div className="flex justify-between">
                  <dt className="text-slate-500">Disk usage</dt>
                  <dd className="font-mono">{fmtBytes(live.disk ?? 0)}</dd>
                </div>
              </dl>
            </div>
          ) : (
            <p className="py-6 text-sm text-slate-500">
              {server.vmid
                ? "Proxmox did not return live stats — the VM may be mid-provision or the API is unreachable."
                : "No VM has been provisioned for this server yet."}
            </p>
          )}
        </div>
      </div>

      {/* Admin actions */}
      <div className="card">
        <h2 className="mb-4 font-semibold">Admin actions</h2>
        <div className="flex flex-wrap items-center gap-x-6 gap-y-4">
          <PowerActions serverId={server.id} status={server.status} />
          <SuspendServerButton serverId={server.id} suspended={server.status === "SUSPENDED"} />
          {!server.isFree && <ExtendForm serverId={server.id} />}
          <FreeToggle serverId={server.id} isFree={server.isFree} />
        </div>
        <p className="mt-3 text-xs text-slate-500">
          Power actions queue a job for the worker — one in-flight job per server. Suspend stops the VM and locks
          customer controls.
        </p>
      </div>

      {/* Job history */}
      <div className="card p-0">
        <h2 className="px-5 pt-5 font-semibold">Job history</h2>
        {server.jobs.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No jobs recorded.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Type</th>
                  <th>Status</th>
                  <th>Attempts</th>
                  <th>Created</th>
                  <th>Updated</th>
                  <th>Detail</th>
                </tr>
              </thead>
              <tbody>
                {server.jobs.map((j) => (
                  <tr key={j.id}>
                    <td className="font-medium">{j.type.toLowerCase().replace(/_/g, " ")}</td>
                    <td>
                      <StatusDot status={j.status} />
                    </td>
                    <td>{j.attempts}</td>
                    <td className="text-xs text-slate-400">{timeAgo(j.createdAt)}</td>
                    <td className="text-xs text-slate-400">{timeAgo(j.updatedAt)}</td>
                    <td className="max-w-md">
                      {j.error ? (
                        <details>
                          <summary className="cursor-pointer text-xs text-red-400">error detail</summary>
                          <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-red-300">
                            {j.error}
                          </pre>
                        </details>
                      ) : j.payload ? (
                        <details>
                          <summary className="cursor-pointer text-xs text-slate-500">payload</summary>
                          <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-slate-400">
                            {JSON.stringify(j.payload, null, 2)}
                          </pre>
                        </details>
                      ) : (
                        <span className="text-xs text-slate-600">—</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Danger zone */}
      <div className="card border-red-500/20">
        <h2 className="mb-1 font-semibold text-red-400">Danger zone</h2>
        <p className="mb-4 text-sm text-slate-400">
          Destroys the VM, its disk, allocated IP and port forwards. This cannot be undone.
        </p>
        <DangerDelete serverId={server.id} hostname={server.hostname} />
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, StatusDot, timeAgo } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";

export const dynamic = "force-dynamic";

export default async function AdminProvisioning() {
  await requireAdmin();

  const since24h = new Date(Date.now() - 24 * 3600_000);

  const [queued, running, failed24h, activeJobs, failedJobs] = await Promise.all([
    db.job.count({ where: { status: "QUEUED" } }),
    db.job.count({ where: { status: "RUNNING" } }),
    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since24h } } }),
    db.job.findMany({
      where: { status: { in: ["QUEUED", "RUNNING"] } },
      include: { server: { select: { id: true, hostname: true } } },
      orderBy: { createdAt: "asc" },
    }),
    db.job.findMany({
      where: { status: "FAILED" },
      include: { server: { select: { id: true, hostname: true } } },
      orderBy: { updatedAt: "desc" },
      take: 30,
    }),
  ]);

  const failedRecent = failedJobs.filter((j) => j.updatedAt >= since24h);
  const avgAttempts =
    failedRecent.length > 0
      ? (failedRecent.reduce((n, j) => n + j.attempts, 0) / failedRecent.length).toFixed(1)
      : "—";

  return (
    <div className="space-y-6">
      <AutoRefresh />
      <PageHeader
        title="Provisioning queue"
        sub="Worker polls the job table every 3 seconds. Failed jobs retry automatically up to 3 attempts."
      />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Queued" value={String(queued)} delta={queued > 0 ? "waiting for worker" : "empty"} deltaGood={queued === 0} />
        <StatCard label="Running" value={String(running)} delta={running > 0 ? "in flight now" : "idle"} />
        <StatCard
          label="Failed · 24h"
          value={String(failed24h)}
          delta={failed24h > 0 ? "inspect below" : "all clear"}
          deltaGood={failed24h === 0}
        />
        <StatCard label="Avg attempts on failed · 24h" value={String(avgAttempts)} delta="of 3 max retries" />
      </div>

      {/* Active jobs */}
      <div className="card p-0">
        <h2 className="px-5 pt-5 font-semibold">Active jobs</h2>
        {activeJobs.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">Nothing in flight — the queue is clear.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Server</th>
                  <th>Type</th>
                  <th>Status</th>
                  <th>Attempts</th>
                  <th className="text-right">Queued</th>
                </tr>
              </thead>
              <tbody>
                {activeJobs.map((j) => (
                  <tr key={j.id}>
                    <td>
                      {j.server ? (
                        <Link href={`/admin/servers/${j.server.id}`} className="font-medium hover:text-brand-300">
                          {j.server.hostname}
                        </Link>
                      ) : (
                        <span className="text-slate-500">system</span>
                      )}
                    </td>
                    <td>{j.type.toLowerCase().replace(/_/g, " ")}</td>
                    <td>
                      <StatusDot status={j.status} />
                    </td>
                    <td>{j.attempts}</td>
                    <td className="text-right text-xs text-slate-400">{timeAgo(j.createdAt)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Failed jobs */}
      <div className="card p-0">
        <div className="px-5 pt-5">
          <h2 className="font-semibold">Failed jobs</h2>
          <p className="mt-1 text-xs text-slate-500">
            Last 30 failures. A job is marked FAILED after exhausting its 3 automatic retries — expand a row for the
            full error.
          </p>
        </div>
        {failedJobs.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No failed jobs on record. Nice.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Server</th>
                  <th>Type</th>
                  <th>Attempts</th>
                  <th>Failed</th>
                  <th>Error</th>
                </tr>
              </thead>
              <tbody>
                {failedJobs.map((j) => (
                  <tr key={j.id}>
                    <td>
                      {j.server ? (
                        <Link href={`/admin/servers/${j.server.id}`} className="font-medium hover:text-brand-300">
                          {j.server.hostname}
                        </Link>
                      ) : (
                        <span className="text-slate-500">system</span>
                      )}
                    </td>
                    <td>{j.type.toLowerCase().replace(/_/g, " ")}</td>
                    <td>{j.attempts}</td>
                    <td className="text-xs text-slate-400">{timeAgo(j.updatedAt)}</td>
                    <td className="max-w-xl">
                      {j.error ? (
                        <details>
                          <summary className="cursor-pointer truncate text-xs text-red-400">
                            {j.error.slice(0, 80)}
                            {j.error.length > 80 ? "…" : ""}
                          </summary>
                          <pre className="mt-1 whitespace-pre-wrap break-all rounded-lg bg-black/30 p-2 font-mono text-[11px] text-red-300">
                            {j.error}
                          </pre>
                        </details>
                      ) : (
                        <span className="text-xs text-slate-600">no error captured</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

