import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { listVms } from "@/lib/proxmox";
import { PageHeader, StatusDot, Badge, fmtBytes } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { NodeMetrics } from "@/components/admin/NodeMetrics";

export const dynamic = "force-dynamic";

export default async function AdminMonitoring() {
  await requireAdmin();

  let vms: any[] = [];
  let pveOk = true;
  try {
    vms = (await listVms()).filter((v) => !v.template);
  } catch {
    pveOk = false;
  }
  vms.sort((a, b) => a.vmid - b.vmid);

  const servers = await db.server.findMany({
    where: { vmid: { not: null } },
    select: { id: true, vmid: true, hostname: true, user: { select: { email: true } } },
  });
  const byVmid = new Map(servers.map((s) => [s.vmid as number, s]));

  return (
    <div className="space-y-6">
      <PageHeader title="Monitoring" sub="Hypervisor time-series metrics and live per-VM resource usage." />

      <NodeMetrics />

      <div className="card p-0">
        <div className="px-5 pt-5">
          <h2 className="font-semibold">Virtual machines</h2>
          <p className="mt-1 text-xs text-slate-500">
            Live from the Proxmox API (templates excluded). VMs without a platform server record are flagged
            unmanaged.
          </p>
        </div>
        {!pveOk ? (
          <p className="px-5 py-8 text-sm text-slate-500">
            Could not reach the Proxmox API — the VM list will reappear once the hypervisor responds.
          </p>
        ) : vms.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No virtual machines on the node.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>VMID</th>
                  <th>Name</th>
                  <th>Owner</th>
                  <th>Status</th>
                  <th>CPU</th>
                  <th className="min-w-40">Memory</th>
                  <th>Disk</th>
                  <th className="text-right">Uptime</th>
                </tr>
              </thead>
              <tbody>
                {vms.map((v) => {
                  const rec = byVmid.get(v.vmid);
                  const orphan = !rec && v.vmid < 9000;
                  const uptimeH = v.uptime ? Math.floor(v.uptime / 3600) : 0;
                  return (
                    <tr key={v.vmid}>
                      <td className="font-mono text-xs">{v.vmid}</td>
                      <td>
                        {rec ? (
                          <Link href={`/admin/servers/${rec.id}`} className="font-medium hover:text-brand-300">
                            {rec.hostname}
                          </Link>
                        ) : (
                          <span className="font-medium">{v.name ?? "—"}</span>
                        )}
                        {orphan && (
                          <span className="ml-2">
                            <Badge tone="amber">unmanaged</Badge>
                          </span>
                        )}
                      </td>
                      <td className="text-xs text-slate-400">{rec?.user.email ?? "—"}</td>
                      <td>
                        <StatusDot status={v.status === "running" ? "online" : "STOPPED"} label={v.status} />
                      </td>
                      <td className="text-xs">
                        {v.status === "running" ? `${((v.cpu ?? 0) * 100).toFixed(1)}% / ${v.cpus} vCPU` : "—"}
                      </td>
                      <td>
                        {v.status === "running" ? (
                          <div>
                            <MeterBar value={v.mem ?? 0} max={v.maxmem ?? 1} color="#3b82f6" />
                            <p className="mt-1 text-[11px] text-slate-500">
                              {fmtBytes(v.mem ?? 0)} / {fmtBytes(v.maxmem ?? 0)}
                            </p>
                          </div>
                        ) : (
                          <span className="text-xs text-slate-600">{fmtBytes(v.maxmem ?? 0)} allocated</span>
                        )}
                      </td>
                      <td className="text-xs">{fmtBytes(v.maxdisk ?? 0)}</td>
                      <td className="text-right text-xs text-slate-400">
                        {v.status === "running" && v.uptime
                          ? uptimeH >= 24
                            ? `${Math.floor(uptimeH / 24)}d ${uptimeH % 24}h`
                            : `${uptimeH}h`
                          : "—"}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { nodeStatus, storageStatus } from "@/lib/proxmox";
import { PageHeader, StatusDot, Badge, ComingSoon, fmtBytes } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";

export const dynamic = "force-dynamic";

const POOLS = [
  { key: "vmdata", label: "vmdata", desc: "2×450GB NVMe ZFS mirror — customer VM disks" },
  { key: "backup", label: "backup", desc: "4TB HDD pool — VM backups, templates, cloud-init snippets" },
  { key: "local", label: "local", desc: "Host root filesystem — Proxmox system, ISOs" },
] as const;

function capColor(ratio: number): string {
  if (ratio > 1) return "#ef4444";
  if (ratio > 0.8) return "#f59e0b";
  return "#34d399";
}

export default async function AdminInfrastructure() {
  await requireAdmin();

  let node: any = null;
  const pools: Record<string, any> = {};
  try {
    node = await nodeStatus();
  } catch {
    node = null;
  }
  await Promise.all(
    POOLS.map(async (p) => {
      try {
        pools[p.key] = await storageStatus(p.key);
      } catch {
        pools[p.key] = null;
      }
    })
  );

  const [servers, templates, ipCount, portCount] = await Promise.all([
    db.server.findMany({
      where: { status: { notIn: ["SUSPENDED", "DELETING"] } },
      select: { plan: { select: { ramMB: true, diskGB: true } } },
    }),
    db.osTemplate.findMany({ orderBy: { vmid: "asc" } }),
    db.server.count({ where: { ipAddress: { not: null } } }),
    db.server.count({ where: { sshPort: { not: null } } }),
  ]);

  // Capacity planning
  const allocRamBytes = servers.reduce((n, s) => n + s.plan.ramMB, 0) * 1024 * 1024;
  const allocDiskBytes = servers.reduce((n, s) => n + s.plan.diskGB, 0) * 1024 ** 3;
  const hostRamBytes = node?.memory?.total ?? 64 * 1024 ** 3;
  const vmdataTotal = pools.vmdata?.total ?? 0;
  const ramRatio = allocRamBytes / hostRamBytes;
  const diskRatio = vmdataTotal > 0 ? allocDiskBytes / vmdataTotal : 0;

  const uptimeDays = node ? Math.floor(node.uptime / 86400) : 0;
  const uptimeHours = node ? Math.floor((node.uptime % 86400) / 3600) : 0;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Infrastructure"
        sub="The physical hardware behind the platform — one dedicated Proxmox VE node."
      />

      <div className="grid gap-4 xl:grid-cols-2">
        {/* Node card */}
        <div className="card">
          <div className="mb-4 flex items-center justify-between">
            <h2 className="font-semibold">Node · {process.env.PROXMOX_NODE ?? "pve"}</h2>
            {node ? <StatusDot status="online" label="online" /> : <StatusDot status="ERROR" label="unreachable" />}
          </div>
          {node ? (
            <dl className="space-y-2.5 text-sm">
              <div className="flex justify-between gap-4">
                <dt className="text-slate-500">CPU model</dt>
                <dd className="text-right">{node.cpuinfo?.model ?? "—"}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Threads</dt>
                <dd>{node.cpuinfo?.cpus ?? "—"}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Memory</dt>
                <dd>
                  {fmtBytes(node.memory?.used ?? 0)} used of {fmtBytes(node.memory?.total ?? 0)}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Kernel</dt>
                <dd className="max-w-64 truncate text-right">
                  {typeof node.kversion === "string" ? node.kversion.split(" ").slice(0, 2).join(" ") : "—"}
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Uptime</dt>
                <dd>
                  {uptimeDays}d {uptimeHours}h
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Load average</dt>
                <dd className="font-mono text-xs">{Array.isArray(node.loadavg) ? node.loadavg.join("  ") : "—"}</dd>
              </div>
            </dl>
          ) : (
            <p className="py-6 text-sm text-slate-500">Proxmox API unreachable — node details unavailable.</p>
          )}
        </div>

        {/* Storage pools */}
        <div className="card">
          <h2 className="mb-4 font-semibold">Storage pools</h2>
          <div className="space-y-5">
            {POOLS.map((p) => {
              const s = pools[p.key];
              return (
                <div key={p.key}>
                  <div className="mb-1.5 flex items-baseline justify-between gap-3">
                    <span className="text-sm font-medium">{p.label}</span>
                    <span className="text-xs text-slate-400">
                      {s ? `${fmtBytes(s.used)} / ${fmtBytes(s.total)} · ${fmtBytes(s.avail)} free` : "unavailable"}
                    </span>
                  </div>
                  {s && <MeterBar value={s.used} max={s.total} color={capColor(s.used / s.total)} />}
                  <p className="mt-1 text-xs text-slate-500">{p.desc}</p>
                </div>
              );
            })}
          </div>
        </div>

        {/* Capacity planning */}
        <div className="card">
          <h2 className="mb-1 font-semibold">Capacity planning</h2>
          <p className="mb-4 text-xs text-slate-500">
            Plan allocations of non-suspended servers vs physical capacity. Amber above 80%, red when overcommitted.
          </p>
          <div className="space-y-5">
            <div>
              <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                <span>RAM committed</span>
                <span>
                  {fmtBytes(allocRamBytes)} / {fmtBytes(hostRamBytes)} · {(ramRatio * 100).toFixed(0)}%
                </span>
              </div>
              <MeterBar value={allocRamBytes} max={hostRamBytes} color={capColor(ramRatio)} />
            </div>
            <div>
              <div className="mb-1.5 flex justify-between text-xs text-slate-400">
                <span>Disk committed (vmdata)</span>
                <span>
                  {fmtBytes(allocDiskBytes)}
                  {vmdataTotal > 0 ? ` / ${fmtBytes(vmdataTotal)} · ${(diskRatio * 100).toFixed(0)}%` : " / pool size unavailable"}
                </span>
              </div>
              <MeterBar value={allocDiskBytes} max={vmdataTotal || allocDiskBytes || 1} color={capColor(diskRatio)} />
            </div>
            {(ramRatio > 1 || diskRatio > 1) && (
              <p className="rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-xs text-red-300">
                Overcommitted — new orders rely on actual usage staying below plan allocations. Consider pausing
                sales or adding a node.
              </p>
            )}
          </div>
        </div>

        {/* Network */}
        <div className="card">
          <h2 className="mb-4 font-semibold">Network</h2>
          <dl className="space-y-2.5 text-sm">
            <div className="flex justify-between">
              <dt className="text-slate-500">Public IP</dt>
              <dd className="font-mono">{process.env.PUBLIC_IP ?? "not set"}</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-500">NAT subnet</dt>
              <dd className="font-mono">10.20.0.0/24 (vmbr1)</dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-500">Guest IPs allocated</dt>
              <dd>
                {ipCount} / 150 <span className="text-xs text-slate-500">(pool 10.20.0.100–250)</span>
              </dd>
            </div>
            <div className="flex justify-between">
              <dt className="text-slate-500">SSH forwards in use</dt>
              <dd>
                {portCount} <span className="text-xs text-slate-500">(range 20000–29999)</span>
              </dd>
            </div>
          </dl>
          <div className="mt-4">
            <MeterBar value={ipCount} max={150} color={capColor(ipCount / 150)} />
            <p className="mt-1 text-xs text-slate-500">IP pool utilisation</p>
          </div>
        </div>
      </div>

      {/* Templates */}
      <div className="card p-0">
        <div className="px-5 pt-5">
          <h2 className="font-semibold">OS templates</h2>
          <p className="mt-1 text-xs text-slate-500">
            Cloud-init templates cloned for new VMs (VMIDs 9000+ are reserved). Managed via the OsTemplate table in
            the database.
          </p>
        </div>
        <div className="overflow-x-auto pt-3">
          <table className="table-shell">
            <thead>
              <tr>
                <th>Name</th>
                <th>Slug</th>
                <th>Template VMID</th>
                <th className="text-right">Status</th>
              </tr>
            </thead>
            <tbody>
              {templates.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-8 text-center text-slate-500">
                    No OS templates registered.
                  </td>
                </tr>
              )}
              {templates.map((t) => (
                <tr key={t.id}>
                  <td className="font-medium">{t.name}</td>
                  <td className="font-mono text-xs">{t.slug}</td>
                  <td className="font-mono text-xs">{t.vmid}</td>
                  <td className="text-right">
                    <Badge tone={t.active ? "green" : "slate"}>{t.active ? "active" : "disabled"}</Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div>
        <h2 className="section-label mb-3">Additional nodes</h2>
        <ComingSoon
          feature="Multi-node scheduling"
          note="The platform currently runs on a single dedicated Proxmox node. Multi-node support (per-node IP pools, least-loaded scheduler) is on the roadmap — additional hypervisors will appear here once it ships."
        />
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, StatusDot, Badge, fmtMoney } from "@/components/ui/primitives";
import { ExtendForm, FreeToggle } from "@/components/SubscriptionControls";

export const dynamic = "force-dynamic";

export default async function AdminSubscriptions() {
  await requireAdmin();

  const [servers, revenueAgg] = await Promise.all([
    db.server.findMany({
      where: { status: { notIn: ["DELETING"] } },
      include: { user: true, plan: true },
      orderBy: [{ isFree: "asc" }, { expiresAt: "asc" }],
    }),
    db.walletTransaction.aggregate({
      where: { amountCents: { lt: 0 } },
      _sum: { amountCents: true },
    }),
  ]);

  const paid = servers.filter((s) => !s.isFree);
  const mrrCents = paid.reduce((sum, s) => sum + s.plan.priceCents, 0);
  const totalRevenueCents = -(revenueAgg._sum.amountCents ?? 0);
  const now = Date.now();
  const overdue = paid.filter((s) => s.expiresAt && s.expiresAt.getTime() < now);

  return (
    <div className="space-y-6">
      <PageHeader title="Subscriptions" sub="Renewal state of every server on the platform." />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-5">
        <StatCard label="Active subscriptions" value={String(paid.length)} />
        <StatCard label="Free servers" value={String(servers.length - paid.length)} delta="no billing" />
        <StatCard label="MRR" value={fmtMoney(mrrCents)} href="/admin/analytics" />
        <StatCard label="Lifetime revenue" value={fmtMoney(totalRevenueCents)} href="/admin/billing" />
        <StatCard
          label="Overdue"
          value={String(overdue.length)}
          delta={overdue.length > 0 ? "past renewal date" : "all current"}
          deltaGood={overdue.length === 0}
        />
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Server</th>
              <th>Client</th>
              <th>Plan</th>
              <th>Status</th>
              <th>Auto-renew</th>
              <th>Paid until</th>
              <th>Adjust</th>
              <th className="text-right">Billing mode</th>
            </tr>
          </thead>
          <tbody>
            {servers.length === 0 && (
              <tr>
                <td colSpan={8} className="py-10 text-center text-slate-500">
                  No servers yet.
                </td>
              </tr>
            )}
            {servers.map((s) => {
              const isOverdue = !s.isFree && s.expiresAt && s.expiresAt.getTime() < now;
              return (
                <tr key={s.id} className={isOverdue ? "bg-red-500/[0.04]" : undefined}>
                  <td>
                    <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
                      {s.hostname}
                    </Link>
                    {s.isFree && (
                      <span className="ml-2">
                        <Badge tone="green">free</Badge>
                      </span>
                    )}
                  </td>
                  <td>
                    <Link href={`/admin/users/${s.userId}`} className="text-slate-300 hover:text-brand-300">
                      {s.user.email}
                    </Link>
                  </td>
                  <td>
                    {s.plan.name}
                    {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(s.plan.priceCents)}/mo</span>}
                  </td>
                  <td>
                    <StatusDot status={s.status} />
                  </td>
                  <td>
                    {s.isFree ? (
                      <span className="text-slate-500">—</span>
                    ) : (
                      <Badge tone={s.autoRenew ? "green" : "slate"}>{s.autoRenew ? "on" : "off"}</Badge>
                    )}
                  </td>
                  <td className={isOverdue ? "font-semibold text-red-400" : ""}>
                    {s.isFree ? "never expires" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
                    {isOverdue && (
                      <span className="ml-2">
                        <Badge tone="red">overdue</Badge>
                      </span>
                    )}
                  </td>
                  <td>{!s.isFree && <ExtendForm serverId={s.id} />}</td>
                  <td className="text-right">
                    <FreeToggle serverId={s.id} isFree={s.isFree} />
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <p className="text-xs text-slate-500">
        Renewal engine: the worker sweeps every 10 minutes — expired servers with auto-renew on and sufficient wallet
        balance are charged and extended 30 days; unpaid servers get a 3-day grace period, are then suspended, and
        restore automatically the moment the client pays.
      </p>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";

export default async function AdminBilling({
  searchParams,
}: {
  searchParams: Promise<{ q?: string; type?: string }>;
}) {
  await requireAdmin();
  const sp = await searchParams;
  const query = (sp.q ?? "").trim();
  const type = sp.type === "charges" || sp.type === "credits" ? sp.type : undefined;

  const since30d = new Date(Date.now() - 30 * 86400_000);

  const [rev30, revAll, credits30, liabilities, transactions] = await Promise.all([
    db.walletTransaction.aggregate({
      where: { amountCents: { lt: 0 }, createdAt: { gte: since30d } },
      _sum: { amountCents: true },
    }),
    db.walletTransaction.aggregate({
      where: { amountCents: { lt: 0 } },
      _sum: { amountCents: true },
    }),
    db.walletTransaction.aggregate({
      where: {
        amountCents: { gt: 0 },
        createdAt: { gte: since30d },
        description: { contains: "Admin credit", mode: "insensitive" },
      },
      _sum: { amountCents: true },
    }),
    db.user.aggregate({ _sum: { balanceCents: true } }),
    db.walletTransaction.findMany({
      where: {
        ...(type === "charges" ? { amountCents: { lt: 0 } } : {}),
        ...(type === "credits" ? { amountCents: { gt: 0 } } : {}),
        ...(query
          ? {
              OR: [
                { description: { contains: query, mode: "insensitive" as const } },
                { user: { email: { contains: query, mode: "insensitive" as const } } },
              ],
            }
          : {}),
      },
      include: { user: { select: { id: true, email: true } } },
      orderBy: { createdAt: "desc" },
      take: 100,
    }),
  ]);

  const stripeConnected = Boolean(process.env.STRIPE_SECRET_KEY);
