        <StatCard label="Revenue · all time" value={fmtMoney(-(revAll._sum.amountCents ?? 0))} delta="since launch" />
        <StatCard
          label="Credits issued · 30d"
          value={fmtMoney(credits30._sum.amountCents ?? 0)}
          delta="admin adjustments"
        />
        <StatCard
          label="Outstanding liabilities"
          value={fmtMoney(liabilities._sum.balanceCents ?? 0)}
          delta="sum of customer wallets"
        />
      </div>

      {/* Stripe status */}
      {stripeConnected ? (
        <div className="card flex items-center justify-between gap-4">
          <div className="flex items-center gap-3">
            <Badge tone="green">Stripe connected</Badge>
            <p className="text-sm text-slate-400">
              STRIPE_SECRET_KEY is configured — checkout top-ups settle via the Stripe webhook.
            </p>
          </div>
        </div>
      ) : (
        <div className="card border-amber-500/30">
          <div className="mb-2 flex items-center gap-3">
            <Badge tone="amber">Stripe not configured</Badge>
            <h2 className="font-semibold">Card payments are disabled</h2>
          </div>
          <p className="mb-3 text-sm text-slate-400">
            Wallet top-ups currently use the demo gateway. To take real card payments, add to{" "}
            <span className="kbd">/opt/nxeon/.env</span>:
          </p>
          <ul className="space-y-1.5 text-sm">
            <li>
              <span className="kbd">STRIPE_SECRET_KEY</span>
              <span className="ml-2 text-slate-400">— secret key from the Stripe dashboard</span>
            </li>
            <li>
              <span className="kbd">STRIPE_WEBHOOK_SECRET</span>
              <span className="ml-2 text-slate-400">— signing secret of the webhook endpoint</span>
            </li>
          </ul>
          <p className="mt-3 text-sm text-slate-400">
            Webhook URL: <span className="kbd">http://{publicIp}/api/stripe/webhook</span> · events:{" "}
            <span className="kbd">checkout.session.completed</span>
          </p>
        </div>
      )}

      {/* Ledger */}
      <div className="card p-0">
        <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-5">
          <h2 className="font-semibold">Transactions</h2>
          <div className="flex items-center gap-2">
            {chip(`/admin/billing?${qs.slice(1)}`, "All", !type)}
            {chip(`/admin/billing?type=charges${qs}`, "Charges", type === "charges")}
            {chip(`/admin/billing?type=credits${qs}`, "Credits", type === "credits")}
          </div>
        </div>
        {transactions.length === 0 ? (
          <p className="px-5 py-10 text-center text-sm text-slate-500">
            No transactions{query ? ` matching “${query}”` : ""}.
          </p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Client</th>
                  <th>Description</th>
                  <th>When</th>
                  <th className="text-right">Amount</th>
                </tr>
              </thead>
              <tbody>
                {transactions.map((t) => (
                  <tr key={t.id}>
                    <td>
                      <Link href={`/admin/users/${t.user.id}`} className="hover:text-brand-300">
                        {t.user.email}
                      </Link>
                    </td>
                    <td className="max-w-md truncate">{t.description}</td>
                    <td className="text-xs text-slate-400">{timeAgo(t.createdAt)}</td>
                    <td className={`text-right font-medium ${t.amountCents < 0 ? "text-red-400" : "text-emerald-400"}`}>
                      {t.amountCents < 0 ? "−" : "+"}
                      {fmtMoney(Math.abs(t.amountCents))}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <p className="px-5 py-4 text-xs text-slate-500">Showing the latest 100 matching entries.</p>
      </div>
    </div>
  );
}

import Link from "next/link";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatCard, StatusDot, Badge, timeAgo } from "@/components/ui/primitives";

export const dynamic = "force-dynamic";

const PRIORITY_ORDER: Record<string, number> = { URGENT: 0, HIGH: 1, NORMAL: 2, LOW: 3 };
const PRIORITY_TONE: Record<string, "red" | "amber" | "brand" | "slate"> = {
  URGENT: "red",
  HIGH: "amber",
  NORMAL: "brand",
  LOW: "slate",
};

export default async function AdminSupport() {
  await requireAdmin();

  const since7d = new Date(Date.now() - 7 * 86400_000);

  const [tickets, closed7d] = await Promise.all([
    db.ticket.findMany({
      include: {
        user: { select: { id: true, email: true, name: true } },
        _count: { select: { messages: true } },
      },
      orderBy: { updatedAt: "desc" },
      take: 200,
    }),
    db.ticket.count({ where: { status: "CLOSED", updatedAt: { gte: since7d } } }),
  ]);

  const open = tickets.filter((t) => t.status === "OPEN").length;
  const awaitingStaff = tickets.filter((t) => t.status === "OPEN" || t.status === "CUSTOMER_REPLY").length;
  const answered = tickets.filter((t) => t.status === "ANSWERED").length;

  const sorted = [...tickets].sort((a, b) => {
    const aClosed = a.status === "CLOSED" ? 1 : 0;
    const bClosed = b.status === "CLOSED" ? 1 : 0;
    if (aClosed !== bClosed) return aClosed - bClosed;
    const p = PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority];
    if (p !== 0) return p;
    return b.updatedAt.getTime() - a.updatedAt.getTime();
  });

  return (
    <div className="space-y-6">
      <PageHeader title="Support desk" sub="Customer tickets, sorted by urgency — urgent first, closed sink." />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Open" value={String(open)} delta={open > 0 ? "unanswered" : "clear"} deltaGood={open === 0} />
        <StatCard
          label="Awaiting staff"
          value={String(awaitingStaff)}
          delta="open + customer replies"
          deltaGood={awaitingStaff === 0}
        />
        <StatCard label="Answered" value={String(answered)} delta="waiting on customer" />
        <StatCard label="Closed · 7d" value={String(closed7d)} delta="resolved this week" />
      </div>

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Subject</th>
              <th>Customer</th>
              <th>Priority</th>
              <th>Status</th>
              <th>Messages</th>
              <th className="text-right">Updated</th>
            </tr>
          </thead>
          <tbody>
            {sorted.length === 0 && (
              <tr>
                <td colSpan={6} className="py-10 text-center text-slate-500">
                  No tickets yet — the queue is empty.
                </td>
              </tr>
            )}
            {sorted.map((t) => (
              <tr key={t.id} className={t.status === "CLOSED" ? "opacity-60" : undefined}>
                <td>
                  <Link href={`/admin/support/${t.id}`} className="font-medium hover:text-brand-300">
                    {t.subject}
                  </Link>
                </td>
                <td>
                  <Link href={`/admin/users/${t.user.id}`} className="text-slate-300 hover:text-brand-300">
                    {t.user.email}
                  </Link>
                </td>
                <td>
                  <Badge tone={PRIORITY_TONE[t.priority] ?? "slate"}>{t.priority.toLowerCase()}</Badge>
                </td>
                <td>
                  <StatusDot status={t.status} />
                </td>
                <td>{t._count.messages}</td>
                <td className="text-right text-xs text-slate-400">{timeAgo(t.updatedAt)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { PageHeader, StatusDot, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { ReplyForm, PrioritySelect, TicketStatusButton } from "@/components/admin/TicketControls";

export const dynamic = "force-dynamic";

export default async function AdminTicket({ params }: { params: Promise<{ id: string }> }) {
  await requireAdmin();
  const { id } = await params;

  const ticket = await db.ticket.findUnique({
    where: { id },
    include: {
      messages: { include: { author: { select: { name: true, role: true } } }, orderBy: { createdAt: "asc" } },
      user: {
        select: {
          id: true,
          name: true,
          email: true,
          balanceCents: true,
          createdAt: true,
          suspended: true,
          _count: { select: { servers: true, tickets: true } },
        },
      },
    },
  });
  if (!ticket) notFound();

  const closed = ticket.status === "CLOSED";

  return (
    <div className="space-y-6">
      <PageHeader title={ticket.subject} sub={`Ticket opened ${ticket.createdAt.toISOString().slice(0, 10)} · updated ${timeAgo(ticket.updatedAt)}`}>
        <StatusDot status={ticket.status} />
        <PrioritySelect ticketId={ticket.id} priority={ticket.priority} />
        <TicketStatusButton ticketId={ticket.id} closed={closed} />
      </PageHeader>

      <div className="grid gap-4 xl:grid-cols-3">
        {/* Thread */}
        <div className="space-y-4 xl:col-span-2">
          <div className="space-y-4">
            {ticket.messages.map((m) => (
              <div key={m.id} className={`flex ${m.isStaff ? "justify-end" : "justify-start"}`}>
                <div
                  className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm ${
                    m.isStaff
                      ? "border border-brand-500/30 bg-brand-500/10"
                      : "glass border border-white/[0.08]"
                  }`}
                >
                  <div className="mb-1.5 flex items-center gap-2 text-xs text-slate-400">
                    <span className="font-medium text-slate-300">{m.author.name}</span>
                    {m.isStaff && <Badge tone="brand">staff</Badge>}
                    <span>{timeAgo(m.createdAt)}</span>
                  </div>
                  <p className="whitespace-pre-wrap leading-relaxed">{m.body}</p>
                </div>
              </div>
            ))}
          </div>

          <div className="card">
            <h2 className="mb-3 font-semibold">Reply as staff</h2>
            {closed ? (
              <p className="text-sm text-slate-500">
                This ticket is closed — reopen it above to continue the conversation.
              </p>
            ) : (
              <ReplyForm ticketId={ticket.id} />
            )}
          </div>
        </div>

        {/* Customer context */}
        <div className="space-y-4">
          <div className="card">
            <h2 className="mb-4 font-semibold">Customer</h2>
            <dl className="space-y-2.5 text-sm">
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Name</dt>
                <dd className="text-right">
                  <Link href={`/admin/users/${ticket.user.id}`} className="font-medium hover:text-brand-300">
                    {ticket.user.name}
                  </Link>
                  {ticket.user.suspended && (
                    <span className="ml-2">
                      <Badge tone="red">suspended</Badge>
                    </span>
                  )}
                </dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Email</dt>
                <dd className="truncate text-right">
                  <Link href={`/admin/users/${ticket.user.id}`} className="hover:text-brand-300">
                    {ticket.user.email}
                  </Link>
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Wallet balance</dt>
                <dd>{fmtMoney(ticket.user.balanceCents)}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Servers</dt>
                <dd>{ticket.user._count.servers}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Tickets total</dt>
                <dd>{ticket.user._count.tickets}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Joined</dt>
                <dd>{ticket.user.createdAt.toISOString().slice(0, 10)}</dd>
              </div>
            </dl>
            <Link href={`/admin/users/${ticket.user.id}`} className="btn-secondary mt-4 w-full text-center">
              Open customer 360 →
            </Link>
          </div>

          <div className="card">
            <h2 className="mb-2 font-semibold">Handling notes</h2>
            <p className="text-xs leading-relaxed text-slate-500">
              Staff replies mark the ticket ANSWERED and notify the customer. A customer reply flips it back to
              needs-attention. Closing is reversible at any time.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

