const [tickets, closed7d, statusCounts] = await Promise.all([
  db.ticket.findMany({
    include: {
      user: { select: { id: true, email: true, name: true } },
      _count: { select: { messages: true } },
    },
    orderBy: { updatedAt: "desc" },
    take: 200,
  }),
  db.ticket.count({ where: { status: "CLOSED", updatedAt: { gte: since7d } } }),
  db.ticket.groupBy({ by: ["status"], _count: true }),
]);

const countOf = (s: string) => statusCounts.find((c) => c.status === s)?._count ?? 0;
const open = countOf("OPEN");
const awaitingStaff = open + countOf("CUSTOMER_REPLY");
const answered = countOf("ANSWERED");
